from flask import Flask

app = Flask(__name__)

@app.route("/")
def home():
    return "مرحبا من صقر كود — Flask يعمل على هاتفك!"

@app.route("/about")
def about():
    return "Flask sample by Saqr Code"

if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5000)

