// خدمة HTTP خفيفة بلا اعتماديات — كافية للتعلم والنماذج الأولية
const http = require("http");

const routes = {
  "/": () => ({ ok: true, message: "مرحبا من صقر كود — خدمة Node تعمل على هاتفك!" }),
  "/about": () => ({ ok: true, service: "node-api", by: "Saqr Code" }),
};

http.createServer((req, res) => {
  const handler = routes[req.url] || (() => ({ ok: false, error: "not found" }));
  res.writeHead(req.url in routes ? 200 : 404, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(handler()));
}).listen(3000, "127.0.0.1", () => console.log("الخدمة تعمل على http://127.0.0.1:3000"));
